const DB_NAME='project-command-404',DB_VERSION=4;
const $=(q,root=document)=>root.querySelector(q);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statuses=['Idea','Planificación','Desarrollo','QA','Release','Publicado','Pausado'];
let db,view='overview',selected=null,filter='',statusFilter='all',projects=[],events=[],tasks=[],milestones=[],bugs=[],decisions=[],releases=[],checks=[],githubSnapshots=[],githubBusy=false,toastTimer;
const uuid=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const now=()=>new Date().toISOString();
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{const d=r.result;for(const name of ['projects','events','tasks','milestones','bugs','decisions','releases','checks','githubSnapshots'])if(!d.objectStoreNames.contains(name))d.createObjectStore(name,{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
const store=(table,mode='readonly')=>db.transaction(table,mode).objectStore(table);
function all(table){return new Promise((resolve,reject)=>{const r=store(table).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function put(table,item){return new Promise((resolve,reject)=>{const r=store(table,'readwrite').put(item);r.onsuccess=resolve;r.onerror=()=>reject(r.error)})}
function remove(table,id){return new Promise((resolve,reject)=>{const r=store(table,'readwrite').delete(id);r.onsuccess=resolve;r.onerror=()=>reject(r.error)})}
function clearTable(table){return new Promise((resolve,reject)=>{const r=store(table,'readwrite').clear();r.onsuccess=resolve;r.onerror=()=>reject(r.error)})}
async function refresh(){projects=(await all('projects')).sort((a,b)=>b.updated.localeCompare(a.updated));events=(await all('events')).sort((a,b)=>b.date.localeCompare(a.date));tasks=await all('tasks');milestones=await all('milestones');bugs=await all('bugs');decisions=await all('decisions');releases=await all('releases');checks=await all('checks');githubSnapshots=await all('githubSnapshots');render()}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('shown');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('shown'),3000)}
async function log(action){await put('events',{id:uuid(),action,date:now()})}
function changeView(next){view=next;selected=null;$('.sidebar').classList.remove('open');document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===next));render()}
const fmt=date=>new Date(date).toLocaleDateString('es-ES',{day:'2-digit',month:'short',year:'numeric'});
const safeProgress=p=>Math.max(0,Math.min(100,Number(p.progress)||0));
function card(p){return `<article class="project-card"><div class="project-head"><span class="project-icon">◈</span><span class="status">${esc(p.status)}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.description||'Sin descripción todavía.')}</p><div class="progress-track"><div style="width:${safeProgress(p)}%"></div></div><div class="project-bottom"><span>${safeProgress(p)}% completado</span><button class="link-btn" data-open="${esc(p.id)}">VER PROYECTO →</button></div></article>`}
function heading(eyebrow,title,sub){return `<div class="eyebrow">${eyebrow}</div><div class="hero"><div><h1>${title}</h1><p>${sub}</p></div><span class="hero-mark">◉ SISTEMA OPERATIVO LOCAL</span></div>`}
function overview(){const active=projects.filter(p=>['Desarrollo','Planificación','QA'].includes(p.status)).length;return heading('OPERATIONS OVERVIEW','Tu centro de mando','Un único espacio para gobernar tus proyectos, desde la idea hasta la publicación.')+`<div class="stats"><div class="stat"><small>PROYECTOS TOTALES</small><strong>${projects.length}</strong><span>Registrados localmente</span></div><div class="stat"><small>EN CURSO</small><strong>${active}</strong><span>Planificación, desarrollo y QA</span></div><div class="stat"><small>PUBLICADOS</small><strong>${projects.filter(p=>p.status==='Publicado').length}</strong><span>Proyectos publicados</span></div><div class="stat"><small>PENDIENTES DE RELEASE</small><strong>${projects.filter(p=>p.status==='Release').length}</strong><span>En preparación</span></div></div><div class="section-row"><h2>Proyectos recientes</h2><button class="link-btn" data-go="projects">VER TODOS →</button></div>${projects.length?`<div class="project-grid">${projects.slice(0,6).map(card).join('')}</div>`:`<div class="empty"><strong>Aún no hay proyectos</strong>Crea tu primer proyecto o carga los ejemplos opcionales.<div class="actions" style="justify-content:center"><button class="primary-btn" data-action="create">＋ Crear proyecto</button><button class="secondary-btn" data-action="demo">Cargar ejemplos</button></div></div>`}<div class="two-col"><section class="panel"><h3>◷ Actividad reciente</h3>${events.length?events.slice(0,5).map(e=>`<div class="activity-item"><span class="activity-point">●</span><div><strong>${esc(e.action)}</strong><time>${fmt(e.date)}</time></div></div>`).join(''):'<p class="hint">Sin actividad todavía.</p>'}</section><section class="panel"><h3>◈ Estado de la plataforma</h3><p class="hint">Almacenamiento IndexedDB local activo.<br>Sin sincronización automática. Las consultas GitHub son explícitas.</p><p class="warning">Radar de proyectos disponible; GitHub Connect y bugs, decisiones, checklist QA y releases disponibles desde cada ficha de proyecto.</p></section></div>`}
function projectsView(){const list=projects.filter(p=>(p.name+' '+p.description).toLowerCase().includes(filter.toLowerCase())&&(statusFilter==='all'||p.status===statusFilter));return heading('PROJECT REGISTRY','Tus proyectos','Crea, actualiza y consulta los proyectos de tu ecosistema.')+`<div class="toolbar"><input class="field" id="searchInput" aria-label="Buscar proyectos" placeholder="Buscar por nombre o descripción…" value="${esc(filter)}"><select class="field" id="statusFilter" aria-label="Filtrar estado"><option value="all">Todos los estados</option>${statuses.map(s=>`<option ${statusFilter===s?'selected':''}>${s}</option>`).join('')}</select><button class="secondary-btn" data-action="create">＋ Crear</button></div>${list.length?`<div class="project-grid">${list.map(card).join('')}</div>`:'<div class="empty"><strong>No hay coincidencias</strong>Prueba otro filtro o crea un nuevo proyecto.</div>'}`}
function detailView(){const p=projects.find(p=>p.id===selected);if(!p){selected=null;return projectsView()}return heading('PROJECT DETAIL',esc(p.name),esc(p.description||'Sin descripción'))+`<div class="detail"><section class="panel"><h3>Ficha del proyecto</h3><dl><dt>Estado</dt><dd>${esc(p.status)}</dd><dt>Progreso</dt><dd>${safeProgress(p)}%</dd><dt>Repositorio</dt><dd>${p.repository?`<a href="${esc(p.repository)}" target="_blank" rel="noopener noreferrer" style="color:var(--accent2)">${esc(p.repository)}</a>`:'No indicado'}</dd><dt>Creado</dt><dd>${fmt(p.created)}</dd><dt>Modificado</dt><dd>${fmt(p.updated)}</dd></dl><div class="progress-track"><div style="width:${safeProgress(p)}%"></div></div><div class="actions"><button class="primary-btn" data-action="edit">Editar proyecto</button><button class="secondary-btn" data-action="back">← Volver</button><button class="danger-btn" data-action="delete">Eliminar</button></div></section><section class="panel"><h3>Plan de ejecución</h3><p class="hint">Tareas, fases, hitos y dependencias disponibles en el tablero Kanban.</p><button class="primary-btn" data-action="kanban">Abrir Kanban →</button><button class="secondary-btn" data-action="analytics">Radar del proyecto →</button><button class="secondary-btn" data-action="quality">Calidad y releases →</button><button class="secondary-btn" data-action="github-project">GitHub Connect →</button></section></div>`}
const taskStates=['Backlog','Por hacer','En curso','En pruebas','Hecho'];
const priorities=['Baja','Media','Alta','Crítica'];
function projectTasks(pid){return tasks.filter(t=>t.projectId===pid)}
function blockers(t){return (t.dependsOn||[]).filter(id=>{const parent=tasks.find(x=>x.id===id);return parent&&parent.status!=='Hecho'})}
function taskBoard(){const p=projects.find(x=>x.id===selected);if(!p)return heading('KANBAN','Tablero de tareas','Selecciona un proyecto para administrar sus tareas.')+`<div class="project-grid">${projects.map(card).join('')}</div>`;
 const ts=projectTasks(p.id);const ms=milestones.filter(m=>m.projectId===p.id);return heading('PROJECT EXECUTION',`Kanban · ${esc(p.name)}`,'Organiza fases, tareas y dependencias sin sincronización automática.')+`<div class="toolbar"><button class="secondary-btn" data-action="back-project">← Ficha</button><button class="primary-btn" data-action="new-task">＋ Tarea</button><button class="secondary-btn" data-action="new-milestone">＋ Hito</button><span class="hint">${ts.filter(t=>t.status==='Hecho').length}/${ts.length} tareas completadas</span></div><div class="milestone-row">${ms.map(m=>`<div class="milestone"><div><b>${esc(m.name)}</b><span>${m.due?esc(m.due):'Sin fecha'} · ${esc(m.status)}</span></div><button class="link-btn" data-milestone="${esc(m.id)}">EDITAR</button></div>`).join('')||'<p class="hint">Todavía no hay hitos. Puedes añadirlos cuando quieras.</p>'}</div><div class="kanban">${taskStates.map(st=>`<section class="kanban-column"><h3>${esc(st)} <small>${ts.filter(t=>t.status===st).length}</small></h3>${ts.filter(t=>t.status===st).sort((a,b)=>priorities.indexOf(b.priority)-priorities.indexOf(a.priority)).map(t=>`<article class="task" draggable="true" data-drag="${esc(t.id)}"><div class="task-top"><span class="priority">${esc(t.priority)}</span><button class="link-btn" data-task="${esc(t.id)}" aria-label="Editar ${esc(t.title)}">✎</button></div><h4>${esc(t.title)}</h4><p>${esc(t.description||'Sin descripción')}</p><div class="task-meta">${t.milestoneId?esc(ms.find(m=>m.id===t.milestoneId)?.name||'Hito eliminado'): 'Sin hito'}${blockers(t).length?` · ⛔ ${blockers(t).length} bloqueo(s)`:''}</div><div class="task-controls"><select aria-label="Mover tarea ${esc(t.title)}" data-move="${esc(t.id)}">${taskStates.map(v=>`<option ${v===t.status?'selected':''}>${v}</option>`).join('')}</select></div></article>`).join('')||'<div class="column-empty">Arrastra aquí o cambia el estado</div>'}</section>`).join('')}</div><p class="hint">Puedes mover tareas con el selector o arrastrarlas entre columnas. Una tarea bloqueada no puede pasar a «Hecho» hasta finalizar sus dependencias.</p>`}
function taskModal(t){const p=projects.find(x=>x.id===selected);if(!p)return;const own=projectTasks(p.id).filter(x=>x.id!==t?.id);const ms=milestones.filter(m=>m.projectId===p.id);$('#modalRoot').innerHTML=`<div class="modal-overlay" id="overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="taskTitle"><h2 id="taskTitle">${t?'Editar':'Nueva'} tarea</h2><form id="taskForm"><label for="taskName">Título *</label><input class="field" id="taskName" name="title" maxlength="110" required value="${esc(t?.title||'')}"><label for="taskDescription">Descripción</label><textarea class="field" id="taskDescription" name="description" maxlength="1000">${esc(t?.description||'')}</textarea><label for="taskStatus">Estado</label><select class="field" name="status" id="taskStatus">${taskStates.map(x=>`<option ${x===(t?.status||'Backlog')?'selected':''}>${x}</option>`).join('')}</select><label for="taskPriority">Prioridad</label><select class="field" name="priority" id="taskPriority">${priorities.map(x=>`<option ${x===(t?.priority||'Media')?'selected':''}>${x}</option>`).join('')}</select><label for="taskMilestone">Hito</label><select class="field" id="taskMilestone" name="milestone"><option value="">Sin hito</option>${ms.map(m=>`<option value="${esc(m.id)}" ${t?.milestoneId===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select><label>Depende de tareas (deben estar terminadas)</label><div class="dependency-list">${own.map(x=>`<label><input type="checkbox" name="dependency" value="${esc(x.id)}" ${(t?.dependsOn||[]).includes(x.id)?'checked':''}> ${esc(x.title)}</label>`).join('')||'<span class="hint">No hay otras tareas.</span>'}</div><div class="actions">${t?'<button type="button" class="danger-btn" id="deleteTask">Eliminar</button>':''}<button type="button" class="secondary-btn" data-close>Cancelar</button><button type="submit" class="primary-btn">Guardar tarea</button></div></form></div></div>`;$('#taskName').focus();$('#taskForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),deps=f.getAll('dependency').map(String),status=String(f.get('status')),title=String(f.get('title')).trim();if(!title)return;const id=t?.id||uuid();if(hasCycle(id,deps)){toast('Dependencia circular: modifica los bloqueos');return}const item={id,projectId:p.id,title,description:String(f.get('description')).trim(),status,priority:String(f.get('priority')),milestoneId:String(f.get('milestone')),dependsOn:deps,created:t?.created||now(),updated:now()};if(status==='Hecho'&&blockers(item).length){toast('Completa antes las tareas de las que depende');return}if(t?.status==='Hecho'&&status!=='Hecho'&&tasks.some(x=>x.status==='Hecho'&&(x.dependsOn||[]).includes(id))){toast('Hay tareas completadas que dependen de esta tarea');return}await put('tasks',item);await log(`Tarea ${t?'actualizada':'creada'}: ${title}`);closeModal();await refresh();toast('Tarea guardada')};if(t)$('#deleteTask').onclick=async()=>{if(tasks.some(x=>x.status==='Hecho'&&(x.dependsOn||[]).includes(t.id))){toast('No puedes eliminar una tarea requerida por tareas completadas');return}if(!confirm(`¿Eliminar tarea «${t.title}»?`))return;await remove('tasks',t.id);for(const dependent of tasks.filter(x=>(x.dependsOn||[]).includes(t.id))){await put('tasks',{...dependent,dependsOn:dependent.dependsOn.filter(x=>x!==t.id)})}await log(`Tarea eliminada: ${t.title}`);closeModal();await refresh()}}
function hasCycle(id,deps){const graph=new Map(tasks.map(t=>[t.id,t.dependsOn||[]]));graph.set(id,deps);function visit(n,seen){if(n===id&&seen.size)return true;if(seen.has(n))return false;const next=new Set(seen);next.add(n);return (graph.get(n)||[]).some(x=>visit(x,next))}return deps.some(x=>visit(x,new Set([id])))}
function milestoneModal(m){const p=projects.find(x=>x.id===selected);if(!p)return;$('#modalRoot').innerHTML=`<div class="modal-overlay" id="overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="milestoneTitle"><h2 id="milestoneTitle">${m?'Editar':'Nuevo'} hito</h2><form id="milestoneForm"><label for="milestoneName">Nombre *</label><input class="field" id="milestoneName" name="name" maxlength="100" value="${esc(m?.name||'')}" required><label for="milestoneDue">Fecha objetivo</label><input class="field" id="milestoneDue" type="date" name="due" value="${esc(m?.due||'')}"><label for="milestoneStatus">Estado</label><select class="field" id="milestoneStatus" name="status">${['Pendiente','En curso','Completado'].map(x=>`<option ${x===(m?.status||'Pendiente')?'selected':''}>${x}</option>`).join('')}</select><div class="actions">${m?'<button class="danger-btn" type="button" id="removeMilestone">Eliminar</button>':''}<button type="button" class="secondary-btn" data-close>Cancelar</button><button type="submit" class="primary-btn">Guardar hito</button></div></form></div></div>`;$('#milestoneName').focus();$('#milestoneForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get('name')).trim();if(!name)return;await put('milestones',{id:m?.id||uuid(),projectId:p.id,name,due:String(f.get('due')),status:String(f.get('status')),created:m?.created||now()});await log(`Hito guardado: ${name}`);closeModal();await refresh()};if(m)$('#removeMilestone').onclick=async()=>{if(!confirm('¿Eliminar este hito? Las tareas quedarán sin hito.'))return;await remove('milestones',m.id);for(const t of tasks.filter(t=>t.milestoneId===m.id))await put('tasks',{...t,milestoneId:''});closeModal();await refresh()}}
async function moveTask(id,to){const t=tasks.find(x=>x.id===id);if(!t||!taskStates.includes(to))return;if(to==='Hecho'&&blockers(t).length){toast('Tarea bloqueada por dependencias');render();return}if(t.status==='Hecho'&&to!=='Hecho'&&tasks.some(x=>x.status==='Hecho'&&(x.dependsOn||[]).includes(id))){toast('Hay tareas completadas que dependen de esta tarea');render();return}await put('tasks',{...t,status:to,updated:now()});await log(`Tarea movida a ${to}: ${t.title}`);await refresh()}

const qualityConfig={bugs:{title:'Bugs',singular:'bug',states:['Abierto','En progreso','Resuelto','Verificado'],create:'new-bug'},decisions:{title:'Decisiones técnicas',singular:'decisión',states:['Propuesta','Aceptada','Descartada'],create:'new-decision'},releases:{title:'Versiones y releases',singular:'release',states:['Borrador','Candidata','Publicada'],create:'new-release'},checks:{title:'Checklist QA',singular:'comprobación',states:['Pendiente','Aprobada','Fallida','No aplica'],create:'new-check'}};
function getQualityStatuses(table){return qualityConfig[table]?.states||[]}
function qualityView(){const p=projects.find(x=>x.id===selected);if(!p)return heading('QUALITY CENTER','Calidad y releases','Selecciona un proyecto para administrar su calidad.')+`<div class="project-grid">${projects.map(card).join('')}</div>`;
let html=heading('QUALITY CENTER',esc(p.name),'Seguimiento de incidencias, decisiones, verificaciones y versiones, todo local.')+`<div class="actions"><button class="secondary-btn" data-action="back">← Proyecto</button><button class="secondary-btn" data-action="kanban">Kanban</button></div>`;
for(const [table,config] of Object.entries(qualityConfig)){const arr=({bugs,decisions,releases,checks})[table].filter(x=>x.projectId===selected).sort((a,b)=>b.created.localeCompare(a.created));html+=`<section class="panel quality-panel"><div class="section-row"><h2>${config.title} (${arr.length})</h2><button class="primary-btn" data-action="${config.create}">＋ Añadir</button></div>${arr.length?arr.map(x=>`<div class="quality-record"><div><strong>${esc(x.title)}</strong><p class="hint">${esc(x.note||'Sin notas')}</p><small>${esc(x.status)} · ${fmt(x.created)}</small></div><div class="actions"><button class="secondary-btn" data-record="${esc(x.id)}" data-table="${table}">Editar</button><button class="danger-btn" data-remove-record="${esc(x.id)}" data-table="${table}">Eliminar</button></div></div>`).join(''):'<p class="hint">No hay registros todavía.</p>'}</section>`}
const openBugs=bugs.filter(x=>x.projectId===selected&&!['Resuelto','Verificado'].includes(x.status)).length;const failedChecks=checks.filter(x=>x.projectId===selected&&x.status==='Fallida').length;const pendingChecks=checks.filter(x=>x.projectId===selected&&x.status==='Pendiente').length;html+=`<section class="panel"><h3>Semáforo de publicación (indicador orientativo)</h3><p class="${openBugs||failedChecks||pendingChecks?'warning':'hint'}">${openBugs} bugs sin resolver · ${failedChecks} comprobaciones fallidas · ${pendingChecks} comprobaciones pendientes.</p><p class="hint">Una checklist vacía o aprobada manualmente NO acredita pruebas automáticas ni certifica una publicación.</p></section>`;return html}
function recordModal(table,item){const c=qualityConfig[table],p=projects.find(x=>x.id===selected);if(!c||!p)return;$('#modalRoot').innerHTML=`<div class="modal-overlay" id="overlay"><div class="modal" role="dialog" aria-modal="true"><h2>${item?'Editar':'Añadir'} ${c.singular}</h2><form id="qualityForm"><label for="qTitle">Título *</label><input id="qTitle" class="field" name="title" maxlength="140" required value="${esc(item?.title||'')}"><label for="qNote">Notas / pasos / criterios</label><textarea id="qNote" class="field" name="note" maxlength="3000">${esc(item?.note||'')}</textarea><label for="qStatus">Estado</label><select id="qStatus" class="field" name="status">${c.states.map(st=>`<option ${item?.status===st?'selected':''}>${st}</option>`).join('')}</select><div class="actions"><button type="button" class="secondary-btn" data-close>Cancelar</button><button type="submit" class="primary-btn">Guardar</button></div></form></div></div>`;$('#qTitle').focus();$('#qualityForm').onsubmit=async ev=>{ev.preventDefault();const form=new FormData(ev.currentTarget),title=String(form.get('title')||'').trim(),note=String(form.get('note')||'').trim(),status=String(form.get('status'));if(!title||title.length>140||note.length>3000||!c.states.includes(status)){toast('Datos no válidos');return}await put(table,{id:item?.id||uuid(),projectId:p.id,title,note,status,created:item?.created||now(),updated:now()});await log(`${c.title}: ${title} (${status})`);closeModal();await refresh();toast('Registro guardado')};}

function activityView(){return heading('AUDIT TRAIL','Registro de actividad','Movimientos realizados dentro de este navegador.')+`<section class="panel">${events.length?events.map(e=>`<div class="activity-item"><span class="activity-point">●</span><div><strong>${esc(e.action)}</strong><time>${new Date(e.date).toLocaleString('es-ES')}</time></div></div>`).join(''):'<p class="hint">Todavía no hay cambios registrados.</p>'}</section>`}
function dataView(){return heading('DATA MANAGEMENT','Tus datos, bajo control','Las copias se descargan en JSON y puedes restaurarlas en otro navegador.')+`<section class="panel"><h3>Exportación y restauración</h3><p class="hint">Se guardan ${projects.length} proyectos, ${tasks.length} tareas, ${milestones.length} hitos, ${bugs.length} bugs, ${decisions.length} decisiones, ${releases.length} releases, ${checks.length} comprobaciones, ${githubSnapshots.length} consultas GitHub y ${events.length} eventos. Los datos permanecen en IndexedDB de este navegador y origen web. Exporta copias periódicamente para evitar pérdidas.</p><div class="data-actions"><button class="primary-btn" data-action="export">↓ Exportar JSON</button><button class="secondary-btn" data-action="import">↑ Importar JSON</button><button class="secondary-btn" data-action="demo">Cargar ejemplos</button><button class="danger-btn" data-action="erase">Borrar todos los datos</button></div><p class="warning">Importar sustituye proyectos, tareas, hitos y actividad actuales: exporta primero una copia. Borrar datos del navegador o cambiar de origen web puede eliminar la información local.</p></section>`}
function aboutView(){return heading('PROJECT INFORMATION','Sobre PROJECT COMMAND 404','La base para un centro de gestión de desarrollo verdaderamente modular.')+`<section class="panel"><h3>Versión 0.7.0 · Pruebas E2E incluidas</h3><p class="hint">Disponible: dashboard real, altas/ediciones/bajas de proyectos, búsqueda, filtros, registro de actividad, tema claro/oscuro, IndexedDB y backup JSON validado.</p><p class="hint">Disponible: Kanban, bugs, decisiones, checklist QA y releases manuales. GitHub Connect: lectura pública de repositorios, issues y releases con importación confirmada. Radar de proyectos con métricas locales y criterios orientativos de QA. Pendiente: GitHub privado y escritura autenticada. No se simulan como funcionalidades existentes.</p><p class="hint">Diseñado para ejecutarse desde un servidor HTTP local o desde GitHub Pages. Sin CDN, frameworks o servicios externos.</p></section>`}
function repoParts(input){
 let url;try{url=new URL(String(input||'').trim())}catch{throw Error('Introduce una URL válida de GitHub')}
 if(url.protocol!=='https:'||url.hostname.toLowerCase()!=='github.com')throw Error('Introduce un repositorio de github.com');
 const m=url.pathname.match(/^\/([A-Za-z0-9-]+)\/([A-Za-z0-9_.-]+)\/?$/);
 if(!m||m[2].endsWith('.git')||m[2]==='.'||m[2]==='..')throw Error('Usa https://github.com/usuario/repositorio');
 return {owner:m[1],repo:m[2],url:`https://github.com/${m[1]}/${m[2]}`};
}
function githubView(){
 const project=projects.find(p=>p.id===selected),snap=project?githubSnapshots.find(g=>g.projectId===project.id):null;
 return heading('GITHUB CONNECT','Integración con GitHub','Lectura de repositorios públicos. Consulta manual y sin credenciales.')+`<section class="panel"><h3>${project?'Repositorio de '+esc(project.name):'Explorar repositorio público'}</h3><p class="hint">La conexión no es automática. Los datos consultados solo se guardan localmente cuando confirmas la importación o actualización.</p><form id="githubLookup" class="github-lookup"><label for="githubUrl">URL del repositorio</label><input class="field" id="githubUrl" type="url" required placeholder="https://github.com/usuario/repositorio" value="${esc(project?.repository||'')}"><button class="primary-btn" type="submit">Consultar GitHub</button></form><p class="warning">Se contactará con api.github.com solo al pulsar «Consultar». GitHub puede aplicar límites de peticiones. No se envían datos del resto de tus proyectos.</p></section><div id="githubResults">${snap?githubSnapshotHTML(snap,project):'<div class="empty"><strong>Sin consulta almacenada</strong>Introduce una URL pública y pulsa Consultar GitHub.</div>'}</div>`;
}
function githubSnapshotHTML(s,p){const r=s.repo,issues=s.issues||[],releasesList=s.releases||[];return `<section class="panel"><h3>${esc(r.full_name)} <span class="status">${r.private?'PRIVADO':'PÚBLICO'}</span></h3><p>${esc(r.description||'Sin descripción')}</p><div class="stats"><div class="stat"><small>STARS</small><strong>${Number(r.stargazers_count)||0}</strong></div><div class="stat"><small>FORKS</small><strong>${Number(r.forks_count)||0}</strong></div><div class="stat"><small>ISSUES ABIERTAS</small><strong>${Number(r.open_issues_count)||0}</strong></div></div><p class="hint">Rama predeterminada: ${esc(r.default_branch)} · Última consulta guardada: ${esc(new Date(s.fetchedAt).toLocaleString('es-ES'))}</p><div class="actions">${p?'<button class="primary-btn" data-action="github-update">Actualizar ficha del proyecto</button>':'<button class="primary-btn" data-action="github-import">Importar como proyecto nuevo</button>'}<a class="secondary-btn" href="${esc(r.html_url)}" target="_blank" rel="noopener noreferrer">Abrir en GitHub ↗</a></div></section><div class="two-col"><section class="panel"><h3>Issues abiertas (${issues.length} consultadas)</h3>${issues.length?issues.map(x=>`<div class="activity-item"><div><a href="${esc(x.html_url)}" target="_blank" rel="noopener noreferrer">#${x.number} · ${esc(x.title)}</a><time>${esc(x.state)}</time></div></div>`).join(''):'<p class="hint">No hay issues en la respuesta consultada.</p>'}</section><section class="panel"><h3>Releases (${releasesList.length} consultadas)</h3>${releasesList.length?releasesList.map(x=>`<div class="activity-item"><div><a href="${esc(x.html_url)}" target="_blank" rel="noopener noreferrer">${esc(x.name||x.tag_name)}</a><time>${esc(x.published_at?.slice(0,10)||'Sin publicar')} · ${x.prerelease?'Prerelease':'Release'}</time></div></div>`).join(''):'<p class="hint">No se han encontrado releases publicadas.</p>'}</section></div>`}
let githubPending=null;
async function githubApi(endpoint){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const response=await fetch('https://api.github.com'+endpoint,{headers:{Accept:'application/vnd.github+json'},signal:controller.signal,cache:'no-store'});if(!response.ok)throw Error(response.status===403?'Límite de GitHub alcanzado o acceso denegado':response.status===404?'Repositorio no encontrado o no público':`GitHub respondió ${response.status}`);return response.json()}finally{clearTimeout(timer)}}
async function queryGithub(url){if(githubBusy)return;let parsed;try{parsed=repoParts(url)}catch(e){toast(e.message);return}githubBusy=true;const root=$('#githubResults');root.innerHTML='<section class="panel"><p class="hint">Consultando GitHub…</p></section>';try{const path=`/repos/${encodeURIComponent(parsed.owner)}/${encodeURIComponent(parsed.repo)}`;const r=await githubApi(path);if(r.private)throw Error('Repositorio no público');const [i,rel]=await Promise.all([githubApi(path+'/issues?state=open&per_page=20'),githubApi(path+'/releases?per_page=20')]);const safeRepo={full_name:r.full_name,description:r.description||'',html_url:r.html_url,private:!!r.private,stargazers_count:r.stargazers_count,forks_count:r.forks_count,open_issues_count:r.open_issues_count,default_branch:r.default_branch};githubPending={id:uuid(),projectId:selected||null,repo:safeRepo,issues:i.filter(x=>!x.pull_request).map(x=>({number:x.number,title:x.title,state:x.state,html_url:x.html_url})),releases:rel.map(x=>({name:x.name,tag_name:x.tag_name,html_url:x.html_url,published_at:x.published_at,prerelease:x.prerelease})),fetchedAt:now()};root.innerHTML=githubSnapshotHTML(githubPending,projects.find(p=>p.id===selected));toast('Consulta completada; decide si quieres guardarla')}catch(e){root.innerHTML=`<section class="panel"><h3>No se pudo consultar GitHub</h3><p class="warning">${esc(e.message)}</p></section>`;toast('Consulta fallida')}finally{githubBusy=false}}
async function saveGithubResult(update){if(!githubPending){toast('Consulta primero un repositorio');return}const item=githubPending,project=projects.find(p=>p.id===selected);if(update){if(!project)return toast('Selecciona un proyecto');if(!confirm(`¿Vincular ${item.repo.full_name} y actualizar nombre/descripción de «${project.name}»?`))return;const next={...project,name:item.repo.full_name,description:item.repo.description.slice(0,500),repository:item.repo.html_url,updated:now()};await put('projects',next);item.projectId=project.id}else{if(!confirm(`¿Crear un proyecto local desde ${item.repo.full_name}?`))return;const p={id:uuid(),name:item.repo.full_name.slice(0,90),description:item.repo.description.slice(0,500),repository:item.repo.html_url,status:'Idea',progress:0,created:now(),updated:now()};await put('projects',p);item.projectId=p.id;selected=p.id}
 for(const old of githubSnapshots.filter(x=>x.projectId===item.projectId))await remove('githubSnapshots',old.id);
 await put('githubSnapshots',item);await log('GitHub: '+(update?'vinculado':'importado')+' '+item.repo.full_name);githubPending=null;await refresh();toast('Datos guardados localmente')}
// Phase 5: deterministic, read-only insights derived from existing local records.
function insightsFor(p, today=new Date().toISOString().slice(0,10)){
 const ts=tasks.filter(t=>t.projectId===p.id),ms=milestones.filter(m=>m.projectId===p.id),bs=bugs.filter(b=>b.projectId===p.id),qs=checks.filter(c=>c.projectId===p.id);
 const open=ts.filter(t=>t.status!=='Hecho'),blocked=open.filter(t=>blockers(t).length>0),overdue=ms.filter(m=>m.due&&m.due<today&&m.status!=='Completado');
 const unresolved=bs.filter(b=>!['Resuelto','Verificado'].includes(b.status)),failed=qs.filter(c=>c.status==='Fallida'),pending=qs.filter(c=>c.status==='Pendiente');
 const critical=open.filter(t=>t.priority==='Crítica'),high=open.filter(t=>t.priority==='Alta');
 const warnings=[];
 if(overdue.length)warnings.push(`${overdue.length} hito(s) vencido(s)`);
 if(blocked.length)warnings.push(`${blocked.length} tarea(s) bloqueada(s)`);
 if(critical.length)warnings.push(`${critical.length} tarea(s) crítica(s) pendiente(s)`);
 if(unresolved.length)warnings.push(`${unresolved.length} bug(s) sin resolver`);
 if(failed.length)warnings.push(`${failed.length} prueba(s) QA fallida(s)`);
 const score=overdue.length*8+blocked.length*6+critical.length*5+high.length*2+unresolved.length*4+failed.length*6+pending.length;
 const releaseReady=ts.length>0&&open.length===0&&qs.length>0&&pending.length===0&&failed.length===0&&unresolved.length===0&&overdue.length===0&&qs.every(c=>['Aprobada','No aplica'].includes(c.status));
 return {project:p,ts,ms,bs,qs,open,blocked,overdue,unresolved,failed,pending,critical,high,warnings,score,releaseReady};
}
function analyticsView(){
 const all=projects.map(p=>insightsFor(p)),sorted=[...all].sort((a,b)=>b.score-a.score||a.project.name.localeCompare(b.project.name));
 const blocked=all.reduce((n,i)=>n+i.blocked.length,0),overdue=all.reduce((n,i)=>n+i.overdue.length,0),openBugs=all.reduce((n,i)=>n+i.unresolved.length,0),ready=all.filter(i=>i.releaseReady).length;
 let html=heading('OPERATIONS INTELLIGENCE','Radar de proyectos','Diagnóstico local calculado en directo. Las prioridades son orientativas y no sustituyen la revisión humana.');
 html+=`<div class="stats"><div class="stat"><small>TAREAS BLOQUEADAS</small><strong>${blocked}</strong><span>Dependencias pendientes</span></div><div class="stat"><small>HITOS VENCIDOS</small><strong>${overdue}</strong><span>Fechas anteriores a hoy</span></div><div class="stat"><small>BUGS ABIERTOS</small><strong>${openBugs}</strong><span>No resueltos ni verificados</span></div><div class="stat"><small>CANDIDATOS QA</small><strong>${ready}</strong><span>Criterios locales mínimos</span></div></div>`;
 html+=`<section class="panel"><h3>Prioridad de atención</h3><p class="hint">Orden por puntuación de riesgos: hitos vencidos (+8), bloqueos (+6), tareas críticas (+5), altas (+2), bugs (+4), QA fallido (+6) y QA pendiente (+1). Una puntuación 0 no demuestra calidad.</p>`;
 html+=sorted.length?sorted.map(i=>`<div class="insight-row"><div><strong>${esc(i.project.name)}</strong><p class="hint">${i.warnings.length?esc(i.warnings.join(' · ')):'Sin alertas de las categorías medidas'} · ${i.open.length}/${i.ts.length} tareas pendientes</p></div><div class="insight-actions"><span class="risk-score">${i.score} pts</span><button class="secondary-btn" data-analytics-project="${esc(i.project.id)}">Analizar →</button></div></div>`).join(''):'<p class="hint">Crea proyectos para mostrar métricas reales.</p>';
 html+='</section><section class="panel"><h3>Cómo interpretar estos datos</h3><p class="hint">«Candidato QA» significa tareas completadas, checklist existente sin pendientes/fallos, sin bugs abiertos ni hitos vencidos. No significa que se hayan ejecutado pruebas automáticas ni que esté lista para publicar. No se crean alertas fuera del navegador.</p></section>';
 return html;
}
function projectInsightView(){
 const p=projects.find(p=>p.id===selected);if(!p)return analyticsView();const i=insightsFor(p);
 return heading('PROJECT DIAGNOSTICS',`Radar · ${esc(p.name)}`,'Indicadores derivados de los datos locales del proyecto.')+`<div class="actions"><button class="secondary-btn" data-action="back-project">← Ficha</button><button class="secondary-btn" data-action="kanban">Kanban</button><button class="secondary-btn" data-action="quality">Calidad y releases</button></div><div class="stats"><div class="stat"><small>TAREAS PENDIENTES</small><strong>${i.open.length}</strong></div><div class="stat"><small>BLOQUEADAS</small><strong>${i.blocked.length}</strong></div><div class="stat"><small>HITOS VENCIDOS</small><strong>${i.overdue.length}</strong></div><div class="stat"><small>RIESGO RELATIVO</small><strong>${i.score}</strong></div></div><section class="panel"><h3>${i.releaseReady?'Candidato a revisión final':'Atención recomendada'}</h3>${i.warnings.length?i.warnings.map(w=>`<div class="activity-item"><span class="activity-point">●</span><strong>${esc(w)}</strong></div>`).join(''):'<p class="hint">Sin alertas detectadas en las categorías medidas.</p>'}<p class="hint">QA: ${i.qs.length} comprobaciones; ${i.pending.length} pendientes; ${i.failed.length} fallidas. ${i.releaseReady?'Cumple las condiciones de candidato QA; requiere validación real antes de publicar.':'No cumple todos los criterios para candidato QA.'}</p></section>`;
}
function render(){const titles={quality:"CALIDAD Y RELEASES",analytics:"RADAR DE PROYECTOS",overview:'CENTRO DE MANDO',projects:'PROYECTOS',board:'KANBAN',activity:'ACTIVIDAD',data:'DATOS Y COPIAS',about:'ACERCA DE',github:'GITHUB CONNECT'};$('#sectionTitle').textContent=titles[view];$('#viewRoot').innerHTML=selected?(view==='board'?taskBoard():view==='quality'?qualityView():view==='analytics'?projectInsightView():view==='github'?githubView():detailView()):({overview,analytics:analyticsView,projects:projectsView,board:taskBoard,quality:qualityView,activity:activityView,data:dataView,about:aboutView,github:githubView}[view]());}
function closeModal(){$('#modalRoot').innerHTML=''}
function formModal(p){const editing=!!p;$('#modalRoot').innerHTML=`<div class="modal-overlay" id="overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><h2 id="modalTitle">${editing?'Editar proyecto':'Nuevo proyecto'}</h2><p class="hint">Información básica del proyecto</p><form id="projectForm"><label for="projectName">Nombre *</label><input class="field" id="projectName" name="name" required maxlength="90" value="${esc(p?.name||'')}" placeholder="Ej. NEURAL 404"><label for="projectDescription">Descripción</label><textarea class="field" id="projectDescription" name="description" maxlength="500" placeholder="Qué hace el proyecto…">${esc(p?.description||'')}</textarea><label for="projectStatus">Estado</label><select class="field" id="projectStatus" name="status">${statuses.map(s=>`<option ${p?.status===s?'selected':''}>${s}</option>`).join('')}</select><label for="projectProgress">Progreso estimado (%)</label><input class="field" id="projectProgress" type="number" name="progress" min="0" max="100" required value="${p?.progress??0}"><label for="projectRepo">URL repositorio GitHub (opcional)</label><input class="field" id="projectRepo" type="url" name="repository" placeholder="https://github.com/usuario/repo" value="${esc(p?.repository||'')}"><div class="actions"><button type="button" class="secondary-btn" data-close>Cancelar</button><button class="primary-btn" type="submit">${editing?'Guardar cambios':'Crear proyecto'}</button></div></form></div></div>`;$('#projectName').focus();$('#projectForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const name=String(f.get('name')||'').trim();const progress=Number(f.get('progress'));const repository=String(f.get('repository')||'').trim();if(!name||!Number.isInteger(progress)||progress<0||progress>100){toast('Comprueba nombre y progreso');return}if(repository){try{const u=new URL(repository);if(u.protocol!=='https:'||u.hostname!=='github.com'||u.search||u.hash||!/^\/[A-Za-z0-9-]+\/[A-Za-z0-9_.-]+\/?$/.test(u.pathname)){throw Error()}}catch{toast('Introduce una URL válida de repositorio GitHub');return}}const item={id:p?.id||uuid(),name,description:String(f.get('description')||'').trim(),status:String(f.get('status')),progress,repository,created:p?.created||now(),updated:now()};await put('projects',item);await log(`${editing?'Proyecto actualizado':'Proyecto creado'}: ${name}`);closeModal();await refresh();toast(editing?'Proyecto actualizado':'Proyecto creado')};}
async function deleteSelected(){const p=projects.find(p=>p.id===selected);if(!p||!confirm(`¿Eliminar "${p.name}"? Esta acción no se puede deshacer.`))return;for(const t of projectTasks(p.id))await remove('tasks',t.id);for(const m of milestones.filter(m=>m.projectId===p.id))await remove('milestones',m.id);for(const table of ['bugs','decisions','releases','checks'])for(const item of ({bugs,decisions,releases,checks})[table].filter(x=>x.projectId===p.id))await remove(table,item.id);for(const snap of githubSnapshots.filter(x=>x.projectId===p.id))await remove('githubSnapshots',snap.id);await remove('projects',p.id);await log(`Proyecto eliminado: ${p.name}`);selected=null;await refresh();toast('Proyecto eliminado')}
async function demo(){if(!confirm('Añadir tres proyectos DEMO claramente identificados a tus datos actuales. ¿Continuar?'))return;const demos=[['DEMO · JARVIS 404','Asistente local para Windows','QA',75],['DEMO · CAU OS','Biblioteca de conocimiento técnico','Release',92],['DEMO · NEURAL 404','Laboratorio de IA local','Desarrollo',42]];for(const [name,description,status,progress] of demos){await put('projects',{id:uuid(),name,description,status,progress,repository:'',created:now(),updated:now()})}await log('Cargados tres proyectos de demostración');await refresh();toast('Ejemplos añadidos')}
function exportJSON(){const data={format:'project-command-404',version:4,exportedAt:now(),projects,events,tasks,milestones,bugs,decisions,releases,checks,githubSnapshots};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`project-command-404-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Copia JSON generada')}
function checkBackup(data){if(!data||data.format!=='project-command-404'||![1,2,3,4].includes(data.version)||!Array.isArray(data.projects)||!Array.isArray(data.events)||data.projects.length>10000||data.events.length>30000)throw Error('Formato o volumen no válido');const ids=new Set();for(const p of data.projects){if(!p||typeof p.id!=='string'||!p.id||ids.has(p.id)||typeof p.name!=='string'||!p.name.trim()||p.name.length>90||typeof p.description!=='string'||p.description.length>500||!statuses.includes(p.status)||!Number.isInteger(p.progress)||p.progress<0||p.progress>100||typeof p.repository!=='string'||typeof p.created!=='string'||!Number.isFinite(Date.parse(p.created))||typeof p.updated!=='string'||!Number.isFinite(Date.parse(p.updated)))throw Error('Datos de proyectos no válidos');if(p.repository){const u=new URL(p.repository);if(u.protocol!=='https:'||u.hostname!=='github.com'||u.search||u.hash||!/^\/[A-Za-z0-9-]+\/[A-Za-z0-9_.-]+\/?$/.test(u.pathname))throw Error('Repositorio no válido')}ids.add(p.id)}ids.clear();for(const e of data.events){if(!e||typeof e.id!=='string'||!e.id||ids.has(e.id)||typeof e.action!=='string'||e.action.length>500||typeof e.date!=='string'||!Number.isFinite(Date.parse(e.date)))throw Error('Eventos no válidos');ids.add(e.id)}if(data.version>=2){if(!Array.isArray(data.tasks)||!Array.isArray(data.milestones)||data.tasks.length>50000||data.milestones.length>10000)throw Error('Volumen de tareas/hitos no válido');const pids=new Set(data.projects.map(p=>p.id)),tids=new Set();for(const t of data.tasks){if(!t||typeof t.id!=='string'||!t.id||tids.has(t.id)||!pids.has(t.projectId)||typeof t.title!=='string'||!t.title.trim()||t.title.length>110||typeof t.description!=='string'||t.description.length>1000||!taskStates.includes(t.status)||!priorities.includes(t.priority)||typeof t.milestoneId!=='string'||!Array.isArray(t.dependsOn)||t.dependsOn.length>500||!t.dependsOn.every(x=>typeof x==='string'))throw Error('Tareas no válidas');tids.add(t.id)}const mids=new Set();for(const m of data.milestones){if(!m||typeof m.id!=='string'||!m.id||mids.has(m.id)||!pids.has(m.projectId)||typeof m.name!=='string'||!m.name.trim()||m.name.length>100||typeof m.due!=='string'||(m.due&&!/^\d{4}-\d{2}-\d{2}$/.test(m.due))||!['Pendiente','En curso','Completado'].includes(m.status))throw Error('Hitos no válidos');mids.add(m.id)}for(const t of data.tasks){if(t.milestoneId&&!mids.has(t.milestoneId))throw Error('Hito inexistente');if(t.dependsOn.some(id=>!tids.has(id)||id===t.id||data.tasks.find(d=>d.id===id)?.projectId!==t.projectId))throw Error('Dependencia inexistente o entre proyectos');if(t.milestoneId&&data.milestones.find(m=>m.id===t.milestoneId)?.projectId!==t.projectId)throw Error('Hito de otro proyecto')}const graph=new Map(data.tasks.map(t=>[t.id,t.dependsOn]));const visiting=new Set(),visited=new Set();function cycle(id){if(visiting.has(id))throw Error('Dependencias circulares en copia');if(visited.has(id))return;visiting.add(id);for(const dep of graph.get(id)||[])cycle(dep);visiting.delete(id);visited.add(id)}for(const id of tids)cycle(id)}}
function isSafeGithubUrl(value){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='github.com'&&!u.username&&!u.password}catch{return false}}
function validateGithubBackup(data){if(data.version<4)return;if(!Array.isArray(data.githubSnapshots)||data.githubSnapshots.length>10000)throw Error('Snapshots GitHub no válidos');const ids=new Set(),pids=new Set(data.projects.map(x=>x.id));for(const x of data.githubSnapshots){if(!x||typeof x.id!=='string'||ids.has(x.id)||!pids.has(x.projectId)||!x.repo||typeof x.repo.full_name!=='string'||typeof x.repo.html_url!=='string'||!Array.isArray(x.issues)||!Array.isArray(x.releases)||x.issues.length>20||x.releases.length>20||!Number.isFinite(Date.parse(x.fetchedAt)))throw Error('Snapshot GitHub inválido');repoParts(x.repo.html_url);if(x.repo.full_name.length>180||JSON.stringify(x).length>150000)throw Error('Snapshot demasiado grande');for(const v of [...x.issues,...x.releases]){if(!v||typeof v.html_url!=='string'||!isSafeGithubUrl(v.html_url)||JSON.stringify(v).length>5000)throw Error('Enlace GitHub inválido')}ids.add(x.id)}}
function validateQualityBackup(data){if(data.version<3)return;const pids=new Set(data.projects.map(p=>p.id));for(const name of ['bugs','decisions','releases','checks']){const arr=data[name];if(!Array.isArray(arr)||arr.length>15000)throw Error('Registros de calidad no válidos');const ids=new Set();for(const x of arr){if(!x||typeof x.id!=='string'||!x.id||ids.has(x.id)||!pids.has(x.projectId)||typeof x.title!=='string'||!x.title.trim()||x.title.length>140||typeof x.note!=='string'||x.note.length>3000||typeof x.status!=='string'||x.status.length>50||typeof x.created!=='string'||!Number.isFinite(Date.parse(x.created)))throw Error('Registro '+name+' no válido');if(!getQualityStatuses(name).includes(x.status))throw Error('Estado de '+name+' no válido');ids.add(x.id)}}}
async function importJSON(file){if(!file)return;if(file.size>8_000_000){toast('Archivo demasiado grande');return}try{const data=JSON.parse(await file.text());checkBackup(data);validateQualityBackup(data);validateGithubBackup(data);if(!confirm(`Se sustituirán ${projects.length} proyectos por ${data.projects.length} proyectos del archivo. Exporta una copia antes. ¿Continuar?`))return;const tx=db.transaction(['projects','events','tasks','milestones','bugs','decisions','releases','checks','githubSnapshots'],'readwrite');const p=tx.objectStore('projects'),e=tx.objectStore('events');p.clear();e.clear();const t=tx.objectStore('tasks'),m=tx.objectStore('milestones');t.clear();m.clear();for(const table of ['bugs','decisions','releases','checks']){const obj=tx.objectStore(table);obj.clear();(data[table]||[]).forEach(item=>obj.put(item))}const gh=tx.objectStore('githubSnapshots');gh.clear();(data.githubSnapshots||[]).forEach(item=>gh.put(item));(data.tasks||[]).forEach(item=>t.put(item));(data.milestones||[]).forEach(item=>m.put(item));data.projects.forEach(item=>p.put(item));data.events.forEach(item=>e.put(item));await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});selected=null;filter='';statusFilter='all';await refresh();toast('Copia restaurada correctamente')}catch(err){console.error(err);toast(`No se pudo importar: ${err.message}`)}finally{$('#importFile').value=''}}
async function erase(){if(!confirm('¿Eliminar DEFINITIVAMENTE todos los proyectos y eventos de este navegador? Exporta antes una copia.'))return;await clearTable('projects');await clearTable('events');await clearTable('tasks');await clearTable('milestones');for(const t of ['bugs','decisions','releases','checks','githubSnapshots'])await clearTable(t);selected=null;await refresh();toast('Datos locales eliminados')}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-view]');if(nav){changeView(nav.dataset.view);return}const go=e.target.closest('[data-go]');if(go){changeView(go.dataset.go);return}const open=e.target.closest('[data-open]');if(open){selected=open.dataset.open;view='projects';document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view==='projects'));render();return}const insight=e.target.closest('[data-analytics-project]');if(insight){selected=insight.dataset.analyticsProject;view='analytics';render();return}const taskEdit=e.target.closest('[data-task]');if(taskEdit){taskModal(tasks.find(x=>x.id===taskEdit.dataset.task));return}const recordEdit=e.target.closest('[data-record]');if(recordEdit){const table=recordEdit.dataset.table;const list={bugs,decisions,releases,checks}[table];if(list)recordModal(table,list.find(x=>x.id===recordEdit.dataset.record));return}const recordDelete=e.target.closest('[data-remove-record]');if(recordDelete){const table=recordDelete.dataset.table;const list={bugs,decisions,releases,checks}[table];const item=list?.find(x=>x.id===recordDelete.dataset.removeRecord&&x.projectId===selected);if(item&&confirm('¿Eliminar este registro?')){await remove(table,item.id);await log('Registro eliminado: '+item.title);await refresh()}return}const milestoneEdit=e.target.closest('[data-milestone]');if(milestoneEdit){milestoneModal(milestones.find(x=>x.id===milestoneEdit.dataset.milestone));return}if(e.target.matches('[data-close]')||e.target.id==='overlay'){closeModal();return}const a=e.target.closest('[data-action]');if(!a)return;switch(a.dataset.action){case'create':formModal();break;case'kanban':view='board';render();break;case'analytics':view='analytics';render();break;case'quality':view='quality';render();break;case'github-project':view='github';githubPending=null;render();break;case'github-import':await saveGithubResult(false);break;case'github-update':await saveGithubResult(true);break;case'new-bug':recordModal('bugs');break;case'new-decision':recordModal('decisions');break;case'new-release':recordModal('releases');break;case'new-check':recordModal('checks');break;case'back-project':view='projects';render();break;case'new-task':taskModal();break;case'new-milestone':milestoneModal();break;case'edit':formModal(projects.find(p=>p.id===selected));break;case'delete':await deleteSelected();break;case'back':selected=null;render();break;case'demo':await demo();break;case'export':exportJSON();break;case'import':$('#importFile').click();break;case'erase':await erase();break;}});
document.addEventListener('submit',e=>{if(e.target.id==='githubLookup'){e.preventDefault();queryGithub($('#githubUrl').value)}});
document.addEventListener('input',e=>{if(e.target.id==='searchInput'){const cursor=e.target.selectionStart;filter=e.target.value;render();const input=$('#searchInput');input.focus();input.setSelectionRange(cursor,cursor)}});
document.addEventListener('dragstart',e=>{const t=e.target.closest('[data-drag]');if(t)e.dataTransfer.setData('text/plain',t.dataset.drag)});document.addEventListener('dragover',e=>{if(e.target.closest('.kanban-column'))e.preventDefault()});document.addEventListener('drop',e=>{const col=e.target.closest('.kanban-column');if(col){e.preventDefault();const id=e.dataTransfer.getData('text/plain');const index=[...col.parentNode.children].indexOf(col);moveTask(id,taskStates[index]).catch(console.error)}});document.addEventListener('change',e=>{if(e.target.matches('[data-move]'))moveTask(e.target.dataset.move,e.target.value).catch(console.error); if(e.target.id==='statusFilter'){statusFilter=e.target.value;render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('.sidebar').classList.remove('open')}});
$('#importFile').addEventListener('change',e=>importJSON(e.target.files[0]));$('#quickCreate').onclick=()=>formModal();$('#menuBtn').onclick=()=>$('.sidebar').classList.toggle('open');
$('#themeBtn').onclick=()=>{const light=document.body.classList.toggle('theme-light');localStorage.setItem('pc404-theme',light?'light':'dark');toast(light?'Tema claro':'Tema oscuro')};
try{if(localStorage.getItem('pc404-theme')==='light')document.body.classList.add('theme-light')}catch{}
(async()=>{try{db=await openDB();await refresh()}catch(err){console.error(err);$('#viewRoot').innerHTML='<div class="empty"><strong>No se pudo abrir IndexedDB</strong>Comprueba los permisos de almacenamiento del navegador y abre la aplicación mediante localhost o HTTPS.</div>';toast('Error de almacenamiento local')}})();
